Pre-requisite For this verification logic:

1. public key: already available at the client browser (probably via config file or hard coded)

2. Body signature: received from the response header (probably with the key name 'sig')

3. Crypto Utility Package: 'node-forge' is used here for react js

       import axios from "axios";
       import storeProvider from "./storeProvider";
       var forge = require("node-forge");
       
       
       /* 
       data: response body 
       header: to get the signature 
       isSkipAuth: to skip this verification check for any api 
       */
       
       const verifySignature = (data, header, isSkipAuth) => {
         return new Promise((resolve, reject) => {
       
           /* this is to get the local public key from the config which is saved in redux this can be hard coded as well */
           const state = storeProvider.getStore().getState();
           if (state.user.publicKey && header && !isSkipAuth) {
             var signature = header.sig;
       
             if (signature) {
               var pki = forge.pki;
               var publicKeyObj = pki.publicKeyFromPem(state.user.publicKey);
       
               // verify RSASSA-PSS signature
               var pss = forge.pss.create({
                 md: forge.md.sha1.create(),
                 mgf: forge.mgf.mgf1.create(forge.md.sha1.create()),
                 saltLength: 20,
                 // optionally pass 'prng' with a custom PRNG implementation
               });
       
               var md = forge.md.sha1.create();
               var finalBody = typeof data === "string" ? data : JSON.stringify(data);
               md.update(finalBody, "utf-8");
       
               var res = publicKeyObj.verify(
                 md.digest().getBytes(),
                 atob(signature),
                 pss
               );
               console.log("verifySignature result = ", res);
       
               if (res) resolve(res);
               else reject(res);
             } else reject(false);
           } else {
             resolve(true);
           }
         });
       };

**Axios post request:**

    function post(url, body, header, isSkipAuth = false) {
      return new Promise((resolve, reject) => {
        axios
          .post(url, body, header)
          .then((res) => {
            verifySignature(res.data, res.headers, isSkipAuth)
              .then((verification) => {
                resolve(res);
              })
              .catch((err) => {
                reject(err);
              });
          })
          .catch((err) => {
            reject(err);
          });
      });
    }

**Axios get request:**

    function get(url, header = undefined, isSkipAuth = false) {
      return new Promise((resolve, reject) => {
        axios
