          .then((res) => {
            verifySignature(res.data, res.headers, isSkipAuth)
              .then((verification) => {
                resolve(res);
              })
              .catch((err) => {
                reject("Signature not verified");
              });
          })
          .catch((err) => {
            reject(err);
          });
      });
    }

